      "rank": 1,
      "ballot_id": "B034",
      "proposed_laureates": [
        "Denis J. Evans",
        "Christopher Jarzynski",
        "Udo Seifert"
      ],
      "assessment": {
        "nobel_worthiness": "A rigorous framework connecting microscopic dynamics to thermodynamic behavior far from equilibrium, with broad reach across statistical physics and experiment.",
        "attribution": "Evans established early fluctuation relations; Jarzynski and Seifert developed influential links between nonequilibrium work, stochastic dynamics, and thermodynamics. Crooks also made a major contribution, so any three-person division compresses a closely connected history.",
        "maturity": "The central relations have survived extensive theoretical and experimental tests and now underpin a mature field.",
        "uncertainties": [
          "The discovery spans several related results, making a sharply bounded citation and fair allocation of credit difficult."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B014",
      "proposed_laureates": [
        "Bertrand I. Halperin",
        "David R. Nelson",
        "A. Peter Young"
      ],
      "assessment": {
        "nobel_worthiness": "The KTHNY theory gave a clear defect-based mechanism for two-dimensional melting and established the hexatic phase, a deep result in statistical mechanics.",
        "attribution": "Halperin, Nelson, and Young jointly developed the theory and its predictions; the collective credit is well matched to the discovery.",
        "maturity": "The framework is decades old and has been tested across systems, with later work refining where its predictions apply.",
        "uncertainties": [
          "Real materials and finite-size effects can complicate identification of the idealized transition sequence."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B016",
      "proposed_laureates": [
        "Michael V. Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "The Aharonov-Bohm effect and Berry phase reveal that phase and geometry have observable consequences, with lasting influence across quantum physics.",
        "attribution": "Aharonov's work established the physical significance of potentials in the Aharonov-Bohm effect; Berry identified the general geometric phase in adiabatic evolution. The two contributions are distinct and complementary.",
        "maturity": "Both effects are firmly established and have become standard concepts with wide experimental and theoretical use.",
        "uncertainties": [
          "The proposed discovery groups two historically separate results under one broad conceptual heading."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Juan Ignacio Cirac"
      ],
      "assessment": {
        "nobel_worthiness": "Ultracold atoms in optical lattices made controlled many-body systems experimentally accessible and enabled direct study of models central to condensed matter physics.",
        "attribution": "Bloch and Greiner were central to experimental realization and landmark demonstrations; Cirac supplied foundational theory for quantum simulation. Zoller and Dalibard also contributed substantially, so the proposed three-name credit is necessarily selective.",
        "maturity": "The platform has developed over decades into a precise and versatile experimental tool, with its basic capabilities repeatedly demonstrated.",
        "uncertainties": [
          "The discovery bundles a broad platform and many milestones, making the boundaries of the prize contribution uncertain."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed precision timekeeping and opened new tests of fundamental physics through exceptionally stable, accurate frequency standards.",
        "attribution": "Katori and Ye independently developed leading approaches that together established the field; recognizing both captures the central experimental contributions.",
        "maturity": "The technology is well validated and has advanced substantially, with real applications and continuing gains in accuracy.",
        "uncertainties": [
          "The ultimate reach of clock comparisons for new fundamental physics is still developing."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B020",
      "proposed_laureates": [
        "John Toner",
        "Tamás Vicsek",
        "Yuhai Tu"
      ],
      "assessment": {
        "nobel_worthiness": "The flocking work identified collective order and long-range correlations in systems without momentum conservation, providing a powerful statistical-physics account of active matter.",
        "attribution": "Vicsek introduced a seminal model, while Toner and Tu developed hydrodynamic theory explaining striking collective behavior. Their complementary roles make a coherent citation.",
        "maturity": "The theory has shaped a mature area and stimulated extensive tests in simulations and experiments.",
        "uncertainties": [
          "How broadly the original universality claims apply across real flocking systems remains an active question."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B048",
      "proposed_laureates": [
        "Peter W. Shor",
        "Andrew M. Steane",
        "Alexei Kitaev"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed that quantum information can be protected in principle and provided essential foundations for fault-tolerant quantum computation.",
        "attribution": "Shor and Steane introduced early quantum codes, while Kitaev developed influential topological approaches to fault tolerance. The selected names represent complementary foundational advances.",
        "maturity": "The theory is well established and experimental platforms have demonstrated increasingly capable error correction, though large-scale fault tolerance remains ahead.",
        "uncertainties": [
          "The field has many foundational contributors beyond these three, and its most consequential practical outcomes are not yet settled."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B013",
      "proposed_laureates": [
        "Juan Maldacena",
        "Edward Witten"
      ],
      "assessment": {
        "nobel_worthiness": "AdS/CFT is a striking duality that reshaped theoretical physics and created powerful connections between quantum field theory and gravity.",
        "attribution": "Maldacena proposed the duality; Witten clarified and extended its structure and consequences. Polyakov's earlier work on related string and gauge ideas makes the broader intellectual lineage important.",
        "maturity": "The correspondence is deeply developed and widely used as a theoretical tool.",
        "uncertainties": [
          "There is no direct empirical confirmation of the duality as a description of nature, and its regime of physical application remains uncertain."
        ]
      }
    }
  ]
